-- c028-v004: cuando * vieron los nativos colgando la criatura de la mano de–él entre sí decían Ciertamente asesino es el hombre este a-quien habiendo-sido-salvado del – mar la Justicia vivir no le-permitió
-- c028-v005: el * pues habiendo-sacudido la criatura a el fuego sufrió ningún mal
-- c028-v006: ellos * esperaban a–él estar-a-punto-de hincharse o caer de-repente muerto por mucho * ellos esperando y viendo nada malo a él sucediendo habiendo-cambiado-de-opinión decían a–él ser un-dios
-- c028-v007: En * los alrededor-de el lugar aquel había propiedades del principal de–la isla de–nombre Póplios quien habiéndonos-acogido a–nosotros días tres amablemente nos-hospedó
-- c028-v008: sucedió * el padre de– Póplios de–fiebres y disentería siendo-afligido estar-postrado ante quien – Paûlos habiendo-entrado y habiendo-orado habiendo-puesto las manos sobre–él lo-sanó a–él
-- c028-v009: esto * habiendo-sucedido también los restantes los en la isla teniendo enfermedades venían y eran-sanados
-- c028-v010: quienes también con–muchos honores nos-honraron a–nosotros y zarpando nos-proveyeron las-cosas para las necesidades
-- c028-v011: Después-de * tres meses zarpamos en barco que-había-invernado en la isla alejandrino con–insignia Dióskouroi
-- c028-v012: y habiendo-atracado en Syrákousai permanecimos días tres
-- c028-v013: de-donde habiendo-costeado llegamos a Rhḗgion y después-de un día habiendo-soplado viento-del-sur al-segundo-día llegamos a Potiólous
-- c028-v014: donde habiendo-encontrado hermanos fuimos-invitados con ellos permanecer días siete y así a – Rhṓmē llegamos
-- c028-v015: y–de-allí los hermanos habiendo-oído las-cosas acerca-de nosotros vinieron a encuentro de–nosotros hasta Foro-de-Appíou Foro y Tres Tabernas a-quienes habiendo-visto – Paûlos habiendo-dado-gracias a– Dios tomó ánimo
-- c028-v016: Cuando * entramos a Rhṓmē el centurión entregó a–los prisioneros al comandante-del-campamento se-le-permitió a– Paûlos permanecer por sí-mismo con el que-lo-custodiaba a–él soldado
-- c028-v017: Sucedió * después-de días tres convocar él a–los que-eran de–los judíos principales habiendo-venido-juntos * ellos decía a ellos Yo varones hermanos nada contrario habiendo-hecho al pueblo o a–las costumbres – de–los-padres prisionero desde Hierosólyma fui-entregado a las manos de–los romanos
-- c028-v018: quienes habiéndome-examinado a–mí querían soltar por – ninguna causa de–muerte existir en mí
-- c028-v019: oponiéndose * los judíos fui-obligado a–apelar a–Káisar no como de–la nación de–mí teniendo algo de–qué–acusar
-- c028-v020: por esta pues – causa os-invité a–vosotros ver y hablar por-causa-de pues la esperanza de– Israḗl la cadena esta llevo
-- c028-v021: ellos * a él dijeron Nosotros ni cartas acerca-de ti recibimos desde – Judea ni habiendo-llegado alguno de–los hermanos anunció o habló algo acerca-de ti malo
-- c028-v022: consideramos-digno * de ti oír lo-que piensas acerca-de * pues la secta esta conocido a–nosotros es que en-todo-lugar es-contradicha
-- c028-v023: Habiendo-señalado * con–él día vinieron a él a el alojamiento más a-quienes exponía testificando el reino de– Dios persuadiendo * a–ellos acerca-de – Iēsoûs desde * la ley de–Mousēs y los profetas desde la-mañana hasta la-tarde
-- c028-v024: y unos * eran-persuadidos por–las-cosas dichas otros * no-creían
-- c028-v025: en-desacuerdo * estando entre sí se-iban habiendo-dicho – Paûlos palabra una que Bien el Espíritu – Santo habló por-medio-de Ēsaïas el profeta a los padres de–vosotros
-- c028-v026: diciendo Ve a el pueblo este y di Con–oído oiréis y no – entenderéis y viendo veréis y no – percibiréis
-- c028-v027: Se-ha-engrosado pues el corazón del pueblo este y con–los oídos pesadamente oyeron y los ojos de–ellos cerraron no-sea-que alguna-vez vean con–los ojos y con–los oídos oigan y con–el corazón entiendan y se-conviertan y los-sane a–ellos
-- c028-v028: conocido pues sea a–vosotros que a–las naciones fue-enviada esta – salvación de– Dios ellos también oirán
-- c028-v029: Y estas-cosas él habiendo-dicho se-fueron los judíos mucha teniendo entre sí-mismos discusión
